/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountPlatformDownload, type PlatformDownloadOptions } from "../../components/platform-download/PlatformDownloadEngine.js";
import type { MotionController } from "../../components/platform-download/motion-runtime";

export function PlatformDownload({ options, className }: { options?: PlatformDownloadOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountPlatformDownload(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="platform-download" />;
}

